// Helper function to display the image (auto-centered)
void drawImage(TFT_eSPI &tft) {
  tft.setRotation(1);
  int16_t disp_w = tft.width();
  int16_t disp_h = tft.height();
  int16_t x = (disp_w - IMAGE_WIDTH) / 2;
  int16_t y = (disp_h - IMAGE_HEIGHT) / 2;
  tft.pushImage(x, y, IMAGE_WIDTH, IMAGE_HEIGHT, image_data);
}

// Alternative method if colors are wrong
void drawImageFixed(TFT_eSPI &tft) {
  tft.setRotation(1);
  int16_t disp_w = tft.width();
  int16_t disp_h = tft.height();
  int16_t x = (disp_w - IMAGE_WIDTH) / 2;
  int16_t y = (disp_h - IMAGE_HEIGHT) / 2;
  for (int py = 0; py < IMAGE_HEIGHT; py++) {
    for (int px = 0; px < IMAGE_WIDTH; px++) {
      uint16_t color = pgm_read_word(&image_data[py * IMAGE_WIDTH + px]);
      color = (color >> 8) | (color << 8);
      tft.drawPixel(x + px, y + py, color);
    }
  }
}
